### ChatClientAgentRunOptions (Extends AgentRunOptions)
```csharp
public class ChatClientAgentRunOptions : AgentRunOptions
{
    // Chat-specific options
    public Microsoft.Extensions.AI.ChatOptions ChatOptions { get; set; }

    // Factory to decorate/replace chat client per-request
    public Func<IChatClient, IChatClient> ChatClientFactory { get; set; }
}
```

### ChatOptions Properties (from IChatClient)
```csharp
public class ChatOptions
{
    // Conversation ID for stateful clients
    public string ConversationId { get; set; }

    // Per-request instructions
    public string Instructions { get; set; }

    // Model parameters
    public float? Temperature { get; set; }           // Randomness
    public int? MaxOutputTokens { get; set; }         // Token limit
    public float? TopP { get; set; }                  // Nucleus sampling
    public int? TopK { get; set; }
    public float? FrequencyPenalty { get; set; }      // Discourage repetition
    public float? PresencePenalty { get; set; }       // Encourage diversity
    public int? Seed { get; set; }                    // Reproducibility

    // Response configuration
    public ChatResponseFormat ResponseFormat { get; set; }  // E.g., JSON schema

    // Tool/Function calling
    public IList<AITool> Tools { get; set; }
    public ChatToolMode? ToolMode { get; set; }       // Auto, Required, None
    public bool AllowMultipleToolCalls { get; set; }

    // Stop sequences
    public IList<string> StopSequences { get; set; }

    // Model ID override
    public string ModelId { get; set; }

    // Background response continuation
    public bool AllowBackgroundResponses { get; set; }
    public ResponseContinuationToken ContinuationToken { get; set; }

    // Additional properties
    public Dictionary<string, object> AdditionalProperties { get; set; }
}
```

**NOTE**: There is NO "MaximumIterations" property in AgentRunOptions or ChatOptions. 
Tool iteration is handled internally by the agent based on tool call results.

