## 6. COMMON WORKFLOW EXAMPLE

```csharp
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// Setup IChatClient (e.g., from OpenAI provider)
var chatClient = new OpenAIChatClient(...);

// Define tools as methods
static string GetWeather(string city) => $"Sunny in {city}";
static int Add(int a, int b) => a + b;

// Create AIFunctions
var tools = new[]
{
    AIFunctionFactory.Create(
        new Func<string, string>(GetWeather),
        "get_weather",
        "Get weather for a city"
    ),
    AIFunctionFactory.Create(
        new Func<int, int, int>(Add),
        "add",
        "Add two numbers"
    )
};

// Create ChatClientAgentOptions
var agentOptions = new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Instructions = "You are a helpful research assistant.",
    ChatOptions = new ChatOptions { Tools = tools }
};

// Create agent
var agent = new ChatClientAgent(chatClient, agentOptions);

// Create session
var session = await agent.CreateSessionAsync();

// Run agent with conversation history
var response = await agent.RunAsync(
    message: "What's the weather in Seattle and what is 5 + 3?",
    session: session,
    options: new ChatClientAgentRunOptions()
);

// Access results
foreach (var message in response.Messages)
{
    Console.WriteLine($"{message.Role}: {message.Text}");
}
```

