using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tool state ---
var notebook = new ResearchNotebook();

// --- Build tools ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (
            [Description("The search query to look up on the web")]
            string query
        ) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Searches the web for information on a topic and returns a list of result snippets with URLs."),

    AIFunctionFactory.Create(
        (
            [Description("A short title for this note")]
            string title,
            [Description("The content to save")]
            string content
        ) => notebook.SaveNote(title, content),
        "save_note",
        "Saves a research note to the notebook for later reference when writing the summary."),

    AIFunctionFactory.Create(
        () => notebook.GetAllNotes(),
        "get_notes",
        "Retrieves all notes saved so far in the notebook."),
};

// --- Build agent ---
OpenAIClient openAIClient = new(apiKey);
IChatClient chatClient = openAIClient.GetChatClient(modelId).AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    instructions: """
        You are a research assistant. When given a topic:
        1. Search the web 2-3 times with different queries to gather diverse information.
        2. Save key findings as notes using the save_note tool.
        3. After gathering enough information, retrieve your notes and write a
           comprehensive summary with key points and source URLs.
        Be thorough but concise. Always cite your sources.
        """,
    tools: tools);

// --- Run the agent ---
Console.WriteLine("🔬 Research Agent");
Console.WriteLine(new string('─', 50));

string topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n📋 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a detailed summary: {topic}")
};

var runOptions = new ChatClientAgentRunOptions(
    new ChatOptions { Temperature = 0f, MaxOutputTokens = 2048 });

await foreach (var update in agent.RunStreamingAsync(messages, session, runOptions))
{
    if (update.ContentUpdate is { } content)
    {
        Console.Write(content);
    }
}

Console.WriteLine("\n\n" + new string('─', 50));
Console.WriteLine($"📝 Notes taken: {notebook.Count}");
Console.WriteLine("✅ Research complete.");

// --- Helpers ---
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? "Recent advances in quantum computing 2025-2026"
        : input;
}

// ====================================================================
// Web Search Tool — uses Bing search via HTML scraping as a fallback
// ====================================================================
static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" }
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var results = ParseResults(html);
            if (results.Count == 0)
            {
                return $"No results found for \"{query}\".";
            }

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for \"{query}\":\n");
            for (int i = 0; i < results.Count; i++)
            {
                var r = results[i];
                sb.AppendLine($"{i + 1}. **{r.Title}**");
                sb.AppendLine($"   URL: {r.Url}");
                sb.AppendLine($"   {r.Snippet}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Please try a different query.";
        }
    }

    private static List<SearchResult> ParseResults(string html)
    {
        var results = new List<SearchResult>();
        var span = html.AsSpan();

        // Parse DuckDuckGo HTML results
        const string resultMarker = "class=\"result__a\"";
        const string snippetMarker = "class=\"result__snippet\"";

        int pos = 0;
        while (results.Count < 5)
        {
            int linkStart = html.IndexOf(resultMarker, pos, StringComparison.Ordinal);
            if (linkStart < 0) break;

            string title = ExtractTagContent(html, linkStart);
            string href = ExtractHref(html, linkStart);
            pos = linkStart + resultMarker.Length;

            int snippetStart = html.IndexOf(snippetMarker, pos, StringComparison.Ordinal);
            string snippet = snippetStart >= 0
                ? ExtractTagContent(html, snippetStart)
                : "(no snippet)";

            if (snippetStart >= 0)
                pos = snippetStart + snippetMarker.Length;

            if (!string.IsNullOrWhiteSpace(title))
            {
                results.Add(new SearchResult(
                    StripHtml(title).Trim(),
                    href,
                    StripHtml(snippet).Trim()));
            }
        }

        return results;
    }

    private static string ExtractHref(string html, int fromIndex)
    {
        int hrefStart = html.LastIndexOf("href=\"", fromIndex, Math.Min(fromIndex, 500), StringComparison.Ordinal);
        if (hrefStart < 0) return "";
        hrefStart += 6;
        int hrefEnd = html.IndexOf('"', hrefStart);
        if (hrefEnd < 0) return "";
        var raw = html[hrefStart..hrefEnd];
        // DuckDuckGo wraps URLs in a redirect; extract the actual URL
        if (raw.Contains("uddg="))
        {
            int uddg = raw.IndexOf("uddg=", StringComparison.Ordinal) + 5;
            int amp = raw.IndexOf('&', uddg);
            var encoded = amp > 0 ? raw[uddg..amp] : raw[uddg..];
            return WebUtility.UrlDecode(encoded);
        }
        return raw;
    }

    private static string ExtractTagContent(string html, int attrPos)
    {
        int gt = html.IndexOf('>', attrPos);
        if (gt < 0) return "";
        int closeTag = html.IndexOf('<', gt + 1);
        if (closeTag < 0) return html[(gt + 1)..];
        return html[(gt + 1)..closeTag];
    }

    private static string StripHtml(string text)
    {
        var sb = new StringBuilder(text.Length);
        bool inTag = false;
        foreach (char c in text)
        {
            if (c == '<') { inTag = true; continue; }
            if (c == '>') { inTag = false; continue; }
            if (!inTag) sb.Append(c);
        }
        return WebUtility.HtmlDecode(sb.ToString());
    }

    private record SearchResult(string Title, string Url, string Snippet);
}

// ====================================================================
// Note-Taking Tool — in-memory notebook
// ====================================================================
sealed class ResearchNotebook
{
    private readonly List<Note> _notes = [];

    public int Count => _notes.Count;

    public string SaveNote(string title, string content)
    {
        var note = new Note(title, content, DateTime.UtcNow);
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        return $"Note \"{title}\" saved successfully (total notes: {_notes.Count}).";
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notebook ({_notes.Count} notes) ===\n");
        for (int i = 0; i < _notes.Count; i++)
        {
            var n = _notes[i];
            sb.AppendLine($"--- Note {i + 1}: {n.Title} ---");
            sb.AppendLine(n.Content);
            sb.AppendLine();
        }

        return sb.ToString();
    }

    private record Note(string Title, string Content, DateTime SavedAt);
}

